import React, { useEffect, useState } from "react";
import { toast } from "sonner";
import { useAuth } from "../context/AuthContext";
import { supabase } from "../lib/supabaseClient";
import { loadAddresses, addAddress, removeAddress, setDefaultAddress } from "../lib/addresses";

export const Orders = () => (
  <div data-testid="orders-page">
    <h2 className="text-2xl mb-6">Os meus pedidos</h2>
    <p className="font-body text-sm text-[var(--da-muted)]" data-testid="orders-empty">
      Ainda não tens encomendas. As tuas compras vão aparecer aqui assim que finalizares o checkout.
    </p>
  </div>
);

export const Profile = () => {
  const { user, profile, refreshProfile } = useAuth();
  const [form, setForm] = useState({ name: "", phone: "" });
  const [saving, setSaving] = useState(false);
  const u = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  useEffect(() => {
    if (profile) setForm({ name: profile.name || "", phone: profile.phone || "" });
  }, [profile]);

  const save = async (e) => {
    e.preventDefault();
    setSaving(true);
    const { error } = await supabase.from("profiles").update({ name: form.name, phone: form.phone }).eq("id", user.id);
    setSaving(false);
    if (error) {
      toast.error("Não foi possível guardar", { description: error.message });
      return;
    }
    await refreshProfile();
    toast.success("Dados atualizados");
  };

  return (
    <div data-testid="profile-page">
      <h2 className="text-2xl mb-6">Os meus dados</h2>
      <form onSubmit={save} className="space-y-4 max-w-lg">
        <Field label="Nome completo" value={form.name} onChange={(v) => u("name", v)} testid="prof-name" />
        <Field label="E-mail" type="email" value={user?.email || ""} onChange={() => {}} testid="prof-email" disabled />
        <Field label="Telemóvel" value={form.phone} onChange={(v) => u("phone", v)} testid="prof-phone" />
        <button disabled={saving} className="btn-da btn-da-primary mt-2 disabled:opacity-60" data-testid="prof-save">
          {saving ? "A guardar…" : "Guardar alterações"}
        </button>
      </form>
    </div>
  );
};

const emptyAddress = { label: "", line1: "", city: "", zip: "", country: "Portugal" };

export const Addresses = () => {
  const { user } = useAuth();
  const [list, setList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState(emptyAddress);
  const u = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const refresh = async () => {
    setList(await loadAddresses(user.id));
    setLoading(false);
  };

  useEffect(() => { refresh(); }, [user.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const submitNew = async (e) => {
    e.preventDefault();
    await addAddress(user.id, form);
    setForm(emptyAddress);
    setAdding(false);
    await refresh();
    toast.success("Morada adicionada");
  };

  const remove = async (id) => {
    await removeAddress(id);
    await refresh();
    toast.success("Morada removida");
  };

  const makeDefault = async (id) => {
    await setDefaultAddress(user.id, id);
    await refresh();
  };

  if (loading) return null;

  return (
    <div data-testid="addresses-page">
      <h2 className="text-2xl mb-6">Moradas</h2>
      <div className="grid sm:grid-cols-2 gap-4">
        {list.map((a) => (
          <div key={a.id} className="border hairline rounded-xl p-5 bg-[var(--da-cream-2)]/40" data-testid={`addr-${a.id}`}>
            <div className="flex items-center justify-between">
              <p className="font-serif-display tracking-[0.1em] text-[var(--da-forest)]">{a.label}</p>
              {a.is_default && <span className="text-[10px] tracking-[0.18em] uppercase bg-[var(--da-leaf)] text-white px-2 py-0.5 rounded-full">Predefinida</span>}
            </div>
            <p className="font-body text-sm mt-3">{a.line1}</p>
            <p className="font-body text-sm">{a.zip} {a.city}</p>
            <p className="font-body text-sm text-[var(--da-muted)]">{a.country}</p>
            <div className="flex gap-2 mt-4">
              {!a.is_default && (
                <button className="btn-da btn-da-ghost text-[11px]" onClick={() => makeDefault(a.id)} data-testid={`addr-${a.id}-default`}>Tornar predefinida</button>
              )}
              <button className="btn-da btn-da-ghost text-[11px] text-red-700" onClick={() => remove(a.id)} data-testid={`addr-${a.id}-remove`}>Remover</button>
            </div>
          </div>
        ))}

        {adding ? (
          <form onSubmit={submitNew} className="border hairline rounded-xl p-5 space-y-2" data-testid="add-address-form">
            <Field label="Nome (ex.: Casa)" value={form.label} onChange={(v) => u("label", v)} testid="addr-new-label" />
            <Field label="Morada" value={form.line1} onChange={(v) => u("line1", v)} testid="addr-new-line1" />
            <div className="grid grid-cols-2 gap-2">
              <Field label="Código postal" value={form.zip} onChange={(v) => u("zip", v)} testid="addr-new-zip" />
              <Field label="Cidade" value={form.city} onChange={(v) => u("city", v)} testid="addr-new-city" />
            </div>
            <div className="flex gap-2 pt-2">
              <button type="submit" className="btn-da btn-da-primary text-[11px]" data-testid="addr-new-save">Guardar</button>
              <button type="button" className="btn-da btn-da-ghost text-[11px]" onClick={() => setAdding(false)}>Cancelar</button>
            </div>
          </form>
        ) : (
          <button onClick={() => setAdding(true)} className="border-2 border-dashed hairline rounded-xl p-5 font-body text-sm text-[var(--da-muted)] hover:text-[var(--da-forest)] hover:border-[var(--da-forest)] transition" data-testid="add-address">
            + Adicionar morada
          </button>
        )}
      </div>
    </div>
  );
};

const Field = ({ label, value, onChange, type = "text", testid, disabled }) => (
  <label className="block">
    <span className="font-body text-xs uppercase tracking-[0.18em] text-[var(--da-forest)]">{label}</span>
    <input type={type} required value={value} disabled={disabled} onChange={(e) => onChange(e.target.value)} data-testid={testid} className="mt-2 w-full bg-white border hairline rounded-lg px-4 py-3 font-body text-sm focus:outline-none focus:border-[var(--da-leaf)] disabled:opacity-60" />
  </label>
);
