import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "../context/AuthContext";

export const Register = () => {
  const navigate = useNavigate();
  const { signUp } = useAuth();
  const [submitting, setSubmitting] = useState(false);
  const [form, setForm] = useState({ firstName: "", lastName: "", email: "", password: "" });
  const u = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const submit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    const name = `${form.firstName} ${form.lastName}`.trim();
    const { error } = await signUp(form.email, form.password, name);
    setSubmitting(false);
    if (error) {
      toast.error("Não foi possível criar a conta", { description: error.message });
      return;
    }
    toast.success("Conta criada", { description: "Bem-vinda à DivinArte." });
    navigate("/conta");
  };

  return (
    <div className="container-da py-16 max-w-md mx-auto" data-testid="register-page">
      <p className="font-script text-[var(--da-leaf)] text-2xl text-center">junta-te a nós</p>
      <h1 className="text-3xl sm:text-4xl text-center mt-1">Criar conta</h1>

      <form onSubmit={submit} className="space-y-4 mt-8" data-testid="register-form">
        <div className="grid grid-cols-2 gap-3">
          <label className="block">
            <span className="font-body text-xs uppercase tracking-[0.18em] text-[var(--da-forest)]">Nome</span>
            <input required value={form.firstName} onChange={(e) => u("firstName", e.target.value)} data-testid="reg-first-name" className="mt-2 w-full bg-white border hairline rounded-lg px-4 py-3 font-body text-sm focus:outline-none focus:border-[var(--da-leaf)]" />
          </label>
          <label className="block">
            <span className="font-body text-xs uppercase tracking-[0.18em] text-[var(--da-forest)]">Apelido</span>
            <input required value={form.lastName} onChange={(e) => u("lastName", e.target.value)} data-testid="reg-last-name" className="mt-2 w-full bg-white border hairline rounded-lg px-4 py-3 font-body text-sm focus:outline-none focus:border-[var(--da-leaf)]" />
          </label>
        </div>
        <label className="block">
          <span className="font-body text-xs uppercase tracking-[0.18em] text-[var(--da-forest)]">E-mail</span>
          <input type="email" required value={form.email} onChange={(e) => u("email", e.target.value)} data-testid="reg-email" className="mt-2 w-full bg-white border hairline rounded-lg px-4 py-3 font-body text-sm focus:outline-none focus:border-[var(--da-leaf)]" />
        </label>
        <label className="block">
          <span className="font-body text-xs uppercase tracking-[0.18em] text-[var(--da-forest)]">Palavra-passe</span>
          <input type="password" required minLength={6} value={form.password} onChange={(e) => u("password", e.target.value)} data-testid="reg-password" className="mt-2 w-full bg-white border hairline rounded-lg px-4 py-3 font-body text-sm focus:outline-none focus:border-[var(--da-leaf)]" />
        </label>
        <button type="submit" disabled={submitting} className="btn-da btn-da-primary w-full disabled:opacity-60" data-testid="reg-submit">
          {submitting ? "A criar…" : "Criar conta"}
        </button>
      </form>

      <p className="font-body text-sm text-[var(--da-muted)] text-center mt-6">
        Já tens conta? <Link to="/conta/login" className="text-[var(--da-forest)] underline" data-testid="reg-go-login">Iniciar sessão</Link>
      </p>
    </div>
  );
};
